function v26ReceiptRoute(s,auto,copy,source,notify){var q=orbaQuickState(),j=oi5Receipt(s),entry=q.attempts[s.oi5Id]||(q.attempts[s.oi5Id]={autoTried:false,requests:0,status:'Receipt ready'});if(auto){if(entry.autoTried)return entry.status;entry.autoTried=true;}if(orbaAttemptRows().some(x=>x.saleId===s.oi5Id&&x.serviceRequest&&['requested','queued','running','submitted','unknown'].includes(x.status)))return 'Previous receipt unresolved · inspect assigned queue in Printers';var rid='receipt-'+v26UUID(),row=orbaAttemptStart(s,Number(SET.pr.paper)||j.media,source,copy);row.serviceRequest=rid;entry.status='Sending to assigned receipt queue';j.state='requested';entry.requests++;v26ServiceFetch('/api/document',{request_id:rid,kind:'receipt',payload:v26ReceiptPayload(s,copy)}).then(()=>v26WatchService(notify,rid)).catch(e=>{row.status=e.rejected?'blocked':'unknown';j.state=row.status;entry.status=e.rejected?'Not sent · '+e.message:'Request outcome unknown · inspect Printers; do not retry blindly';if(notify)notify();});return entry.status;}
function v26LabelRoute(j,notify){j.serviceRequest='label-'+v26UUID();j.serviceState='requested';v26ServiceFetch('/api/document',{request_id:j.serviceRequest,kind:'label',payload:{media:String(j.media.w),dpi:j.media.dpi,lines:j.lines.map(l=>({code:l.code,name:l.name,variant:l.variant,q:l.q}))}}).then(()=>v26WatchService(notify,j.serviceRequest)).catch(e=>{j.serviceState=e.rejected?'failed':'unknown';j.serviceError=e.message;if(notify)notify();});}

/* Stock Finalization UI: local training data only. */
function sfStore(){let st=SET.sfStock||(SET.sfStock={categories:[],meta:Object.create(null),history:[]});if(!st.categoryNodes){st.categorySeq=0;st.categoryNodes=st.categories.map(name=>({id:'CG-'+(++st.categorySeq),name,parent:''}));for(let m of Object.values(st.meta)){m.categoryId=st.categoryNodes.find(n=>n.name===m.category)?.id||'';}}return st;}
function sfMeta(key){let st=sfStore(),m=st.meta[key]||{},node=st.categoryNodes.find(n=>n.name===m.category);if(node)m.categoryId=node.id;else if(!m.category)m.categoryId='';return m;}
function m2Node(id){return sfStore().categoryNodes.find(n=>n.id===id);}
function m2Name(name){return sfStore().categoryNodes.find(n=>n.name===name);}
function m2Path(n){let out=[],seen=new Set();while(n&&!seen.has(n.id)){seen.add(n.id);out.unshift(n.name);n=m2Node(n.parent);}return out.join(' / ');}
function m2Under(id,root){let seen=new Set();while(id&&!seen.has(id)){if(id===root)return true;seen.add(id);id=m2Node(id)?.parent||'';}return false;}
function m2Match(key,cat){let n=m2Node(cat);return !cat||!!n&&m2Under(sfMeta(key).categoryId,n.id);}
function m2Nodes(){return sfStore().categoryNodes.slice().sort((a,b)=>m2Path(a).localeCompare(m2Path(b)));}
function m2Sync(){let st=sfStore();st.categories=st.categoryNodes.map(n=>n.name);}
function m2ValidName(raw,except){let n=String(raw).trim().replace(/\s+/g,' ');if(!n||n.length>40||[...sfStore().categoryNodes.filter(x=>x.id!==except).map(x=>x.name),'All','Ladies','Women','Men','Kids','Bags','Accessories','Shoe care'].some(c=>c.toLowerCase()===n.toLowerCase()))throw Error('Enter a unique category name (1–40 characters)');return n;}
function m2ChangeLog(action,extra){sfStore().history.push({action,at:new Date().toISOString(),...extra});}
function m2Rename(id,raw){let n=m2Node(id);if(!n)throw Error('Category no longer exists');let name=m2ValidName(raw,id),old=n.name;if(name===old)return;let st=sfStore();for(let key of Object.keys(st.meta)){let m=sfMeta(key);if(m.categoryId===id){m.category=name;m.categoryId=id;}}n.name=name;m2Sync();m2ChangeLog('category rename',{id,old,name});}
function m2Move(id,parent){let n=m2Node(id);if(!n||parent&&(!m2Node(parent)||m2Under(parent,id)))throw Error('Cannot move a category into itself or its descendants');let old=n.parent;n.parent=parent;m2ChangeLog('category move',{id,old,parent});}
function m2Merge(id,target){let n=m2Node(id),t=m2Node(target);if(!n||!t||m2Under(target,id))throw Error('Choose a category outside the source subtree');let st=sfStore();for(let m of Object.keys(st.meta).map(sfMeta))if(m.categoryId===id){m.category=t.name;m.categoryId=t.id;}st.categoryNodes.forEach(c=>{if(c.parent===id)c.parent=target;});st.categoryNodes=st.categoryNodes.filter(c=>c.id!==id);st.filterRenames=st.filterRenames||Object.create(null);st.filterRenames[id]=target;m2Sync();m2ChangeLog('category merge',{id,target});}
function m2Delete(id){let n=m2Node(id),st=sfStore();if(!n||st.categoryNodes.some(c=>c.parent===id)||Object.keys(st.meta).map(sfMeta).some(m=>m.categoryId===id))throw Error('Move assigned articles and child categories before deleting');st.categoryNodes=st.categoryNodes.filter(c=>c.id!==id);m2Sync();m2ChangeLog('category delete',{id});}
function m2ParentOptions(selected,exclude){return '<option value="">Top-level category</option>'+m2Nodes().filter(n=>!exclude||!m2Under(n.id,exclude)).map(n=>'<option value="'+oi3Esc(n.id)+'" '+(n.id===selected?'selected':'')+'>'+oi3Esc(m2Path(n))+'</option>').join('');}

function sfArchivedCode(code){let r=oi3State().byCode[code];return !!r&&!!sfMeta(r.scope+':'+r.id).archived;}
function sfArchivedItem(it){return !!it&&!!sfMeta(it.oi5Foot?'footwear:'+(it.fwGroup||it.oi5Article):'generic:'+it.id).archived;}
function sfDialog(id,title,body,refresh){let old=document.getElementById(id);if(old)old.remove();let prev=document.activeElement,x=document.createElement('dialog');x.id=id;x.className='sf-dialog';x.setAttribute('aria-labelledby',id+'-title');x.innerHTML='<header><div><p>ORBA · STOCK</p><h2 id="'+id+'-title">'+oi3Esc(title)+'</h2></div><button type="button" data-sf-close aria-label="Close '+oi3Esc(title)+'">Close</button></header><div class="sf-body">'+body+'<p class="sf-message" role="status" aria-live="polite"></p></div>';document.body.append(x);x.querySelector('[data-sf-close]').onclick=()=>x.close();x.addEventListener('close',()=>{x.remove();if(refresh)refresh();if(prev?.isConnected)prev.focus();});x.showModal();return x;}
