function m5CartonManager(refresh,back,initial=''){let e=oi3Esc,x=sfDialog('m5-carton-manager','Carton barcodes','<p class="sf-help">Register an external carton barcode against one article and one colour. Its saved size distribution stays fixed even if a reusable template changes.</p><div id="m5-carton-list"></div><button class="sf-primary" id="m5-new-carton">Register carton barcode</button><button id="m5-carton-back">Back to scanner</button>',null);let list=x.querySelector('#m5-carton-list');function render(){list.innerHTML=m5Cartons().length?m5Cartons().map((c,i)=>'<div class="m5-match"><small>'+(c.active?'ACTIVE':'RETIRED')+'</small><b>'+e(c.name)+'</b><span>'+e(c.code)+' · '+c.lines.reduce((n,l)=>n+l.quantity,0)+' pairs/carton</span><button data-m5-pack="'+i+'" '+(!c.active?'disabled':'')+'>View / receive</button>'+(c.active?'<details><summary>Retire this barcode</summary><label>Reason<input data-m5-retire-reason="'+i+'" maxlength="120"></label><button data-m5-retire="'+i+'">Retire permanently</button></details>':'')+'</div>').join(''):'<p class="sf-help">No carton barcodes registered yet.</p>';list.querySelectorAll('[data-m5-pack]').forEach(b=>b.onclick=()=>{let c=m5Cartons()[Number(b.dataset.m5Pack)];x.close();m5ReceiveCarton(c,refresh,()=>m5CartonManager(refresh,back));});list.querySelectorAll('[data-m5-retire]').forEach(b=>b.onclick=()=>{try{scLocal();let i=Number(b.dataset.m5Retire),c=m5Cartons()[i],reason=list.querySelector('[data-m5-retire-reason="'+i+'"]').value.trim();if(!c.active||reason.length<5)throw Error('Enter a retirement reason (at least 5 characters)');c.active=false;c.retiredAt=new Date().toISOString();c.retireReason=reason;render();}catch(err){sfError(x,err);}});}x.querySelector('#m5-new-carton').onclick=()=>{x.close();m5RegisterCarton(refresh,()=>m5CartonManager(refresh,back),initial);};x.querySelector('#m5-carton-back').onclick=()=>{x.close();back?.();};render();}
