/* M6 — session-based sellable stocktakes. Local training, no identity/auth service. */
function m6Store(){return SET.m6Stocktake||(SET.m6Stocktake={seq:0,sessions:[]});}
function m6Rows(){return v26Catalogue().rows.filter(r=>!sfArchivedCode(r.code));}
function m6Category(r,id){let node=m2Node(sfMeta(r.scope+':'+r.id).categoryId),seen=new Set();while(node&&!seen.has(node.id)){if(node.id===id)return true;seen.add(node.id);node=m2Node(node.parent);}return false;}
function m6Scope(mode,target){let rows=m6Rows();if(mode==='article')rows=rows.filter(r=>r.scope+':'+r.id===target);else if(mode==='core')rows=rows.filter(r=>r.cat===target);else if(mode==='custom')rows=rows.filter(r=>m6Category(r,target));else if(mode==='cycle')rows=rows.filter(r=>!r.held).sort((a,b)=>a.qty-b.qty||a.code.localeCompare(b.code)).slice(0,Number(target));return rows;}
function m6Line(r){return {code:r.code,key:r.scope+':'+r.id,name:r.name,article:r.article,variant:[r.colour,r.size].filter(Boolean).join(' · '),unit:r.unit,expected:r.qty,held:r.held,damaged:r.damaged,transit:r.transit,checkpoint:scHistory().length,raw:''};}
function m6Stale(l,rows){let r=rows.get(l.code);return !r||r.held>0||r.qty!==l.expected||r.held!==l.held||r.damaged!==l.damaged||r.transit!==l.transit||scHistory().slice(l.checkpoint).some(h=>h.code===l.code);}
function m6Number(l){if(l.raw==='')return null;if(!/^\d+$/.test(l.raw))throw Error('Enter whole quantities (0–999999)');return v21Qty(Number(l.raw),true);}
function m6Validate(s,partial,zeroAck){let rows=new Map(m6Rows().map(r=>[r.code,r])),lines=s.lines.filter(l=>l.raw!=='');if(!lines.length)throw Error('Count at least one variant');if(lines.length!==s.lines.length&&!partial)throw Error('Count every variant or explicitly submit a partial count');if(lines.some(l=>m6Stale(l,rows)))throw Error('Stock changed, is reserved or archived. Reopen and refresh affected counts before approval.');if(lines.some(l=>m6Number(l)===0&&l.expected>0)&&!zeroAck)throw Error('Confirm actual zero counts explicitly');if(SET.scHistoryIncomplete)throw Error('Movement history incomplete; do not apply stocktake');return lines;}
function m6Apply(s,role){scLocal();v21Owner(role);if(s.status!=='review')throw Error('Only a submitted count can be approved');let lines=m6Validate(s,s.partial,s.zeroAck),st=v21State(),seq=st.seq,oldCounts=st.counts.length,oldHistory=scHistory().length,oldAdj={...STOCK_ADJ},oldKeep=KEEP['Inventory|shoes'],oldFeet=oldKeep?.data;try{let results=lines.map(l=>v21Count(l.code,m6Number(l),l.expected,s.id+' · '+s.reason.slice(0,75),role));if(SET.scHistoryIncomplete)throw Error('Movement history incomplete');s.status='approved';s.approvedAt=new Date().toISOString();s.results=results;return results;}catch(err){Object.keys(STOCK_ADJ).forEach(k=>delete STOCK_ADJ[k]);Object.assign(STOCK_ADJ,oldAdj);if(oldKeep){KEEP['Inventory|shoes']=oldKeep;if(oldFeet===undefined)delete oldKeep.data;else oldKeep.data=oldFeet;}else delete KEEP['Inventory|shoes'];st.counts.length=oldCounts;st.seq=seq;scHistory().length=oldHistory;throw err;}}
