function history(){out.innerHTML='<p class="sf-help">Changes to pricing rules, not stock movements. Training session only.</p>'+btn('m8-back','Back to offers')+'<div class="m8-stack">'+(m8History().length?m8History().slice().reverse().map(h=>'<section class="m8-card"><b>'+e(h.action+' · '+h.name)+'</b><small>'+e(typeLabel(h.type))+' · '+e(h.at.slice(0,19).replace('T',' '))+'</small></section>').join(''):'<p>No offer changes yet.</p>')+'</div>';$('m8-back').onclick=home;}
