/* M10 — read-only inventory analytics, with explicit owner-reviewed cost basis. Local training only. */
function m10Store(){return SET.m10Analytics||(SET.m10Analytics={basis:Object.create(null),events:[]});}
function m10Label(r){return [r.name,r.article,r.colour,r.size].filter(Boolean).join(' · ');}
